# captouch_designer_demo.py -- read a slider/wheel made with captouch-designer
#  uses "captouch_pos.py" library
# 30 Oct 2026 - @todbot / Tod Kurt
#
import time
import board
import touchio

from captouch_pos import slider_pos

# replace with "CircuitPython" export from captouch-designer
# Default is the touchwheel0 board. Paste into "Load design" to see it there.
# CapWheel_3ch_D31_ID12 : generated by Captouch Slider Designer
# Values are CH0, CH1, ... order. pos 0 at -60 deg (12 o'clock = 0, clockwise), 1 = one full turn
SLIDER = {
    "mode": "wheel",
    "angle": (60, 180, 300),
    "travel": 360,
    "units": "deg",
    "design": {"type":"wheel","n":3,"tines":7,"overlap":87,"clr":0.4,"tip":0.2,"finger":9,"L":60,"W":12,"ends":"split","split":"last","pad":1,"aRo":30,"aRi":18,"aCenter":0,"sweep":120,"wRo":15.5,"wRi":6,"rot":0,"mask":"covered"},
}

# touchwheel0 pads P0 (12 o'clock), P2 (4 o'clock), P1 (8 o'clock) are CH0-CH2,
# on its header pins 4, 2, 3. With the header in Pico pins 23-26 (GND first):
touch_pins = (board.GP20, board.GP18, board.GP19)  # CH0, CH1, CH2
touchins = [touchio.TouchIn(p) for p in touch_pins]
# untouched baseline, so don't touch the slider at startup
bases = [t.raw_value for t in touchins]

while True:
    # fraction above baseline, like the touchwheel demos' a_pct etc.
    vals = [(t.raw_value - b) / b for t, b in zip(touchins, bases)]
    pos = slider_pos(SLIDER, vals)
    if pos is not None:
        print("pos: %.3f  (%.1f %s)" % (pos, pos * SLIDER["travel"], SLIDER["units"]))
    else:
        print("no touch")
    time.sleep(0.05)
